def save_text(path, text):
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)

def load_text(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read()

save_text("_q_note.txt", "Hi\n")
print(load_text("_q_note.txt").strip())

